class Solution:
    def numberOfSequence(self, n: int, sick: List[int]) -> int:
        MOD = 10**9 + 7

        # Finding gaps between infected children
        gaps = []
        last_sick = -1

        for i in range(len(sick)):
            if last_sick == -1:
                # Gap from start to the first infected child
                gaps.append(sick[i])
            else:
                # Gap between two infected children
                gaps.append(sick[i] - last_sick - 1)
            last_sick = sick[i]

        # Gap from the last infected child to the end
        if last_sick != n - 1:
            gaps.append(n - last_sick - 1)

        # Total ways to arrange infection sequences in the gaps
        total_ways = 1

        for gap in gaps:
            # For each gap, we can infect at most 'gap' children
            if gap > 0:
                total_ways = total_ways * (gap + 1) % MOD

        return total_ways
